/* Cottage Meadow music (generated by tools/build_game_music.py from demos/*.html; do not edit by hand).
   Piano / harp / pad songs that play on the game's AudioContext. The chiptune songs stay in index.html (SONGS). */
const MUSIC={mods:{},_E:null,
  engine(){if(this._E)return this._E;if(typeof audioInit==='function')audioInit();const ac=AC;if(!ac)return{};
    const out=ac.createGain();out.gain.value=.55;out.connect(master);
    const len=ac.sampleRate*2.2,ir=ac.createBuffer(2,len,ac.sampleRate);
    for(let ch=0;ch<2;ch++){const a=ir.getChannelData(ch);for(let i=0;i<len;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/len,3.2);}
    const rev=ac.createConvolver();rev.buffer=ir;const rg=ac.createGain();rg.gain.value=.32;rev.connect(rg);rg.connect(out);
    return this._E={AC:ac,out,rev};}};
MUSIC.mods.village=(function(){

const NOTE={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
const midi=n=>{const m=/([A-G])(#?)(\d)/.exec(n);return NOTE[m[1]]+(m[2]?1:0)+(+m[3]+1)*12;};
const hz=m=>440*Math.pow(2,(m-69)/12);
const SQ=s=>s.trim().split(/\s+/).map(t=>{const[n,l]=t.split(':');return[n==='-'?0:midi(n),+l];});
// the village ("day") song, exactly as in the game
const MEL=SQ(`B4:2 D5:2 G5:4 F#5:2 E5:2 D5:4 C5:2 E5:2 A5:4 G5:2 F#5:2 E5:4 D5:2 G5:2 B5:3 A5:1 G5:2 E5:2 D5:4 C5:2 B4:2 A4:2 F#4:2 G4:8`);
const BAS=SQ(`G2:8 D3:8 C3:8 A2:8 G2:8 E3:8 C3:4 D3:4 G2:8`);
const ARP=SQ(`-:2 G4:2 B4:2 D5:2 -:2 E4:2 G4:2 C5:2 -:2 G4:2 B4:2 D5:2 -:2 D4:2 F#4:2 A4:2`);
const LOOP=64;   // units per loop
// chord per 8-unit bar (for the piano left hand + string pad)
const CH=[['G2','D3','G3','B3'],['D3','A3','D4','F#4'],['C3','G3','C4','E4'],['A2','E3','A3','C4'],['G2','D3','G3','B3'],['E2','B2','E3','G3'],['C3','G3','C4','E4'],['G2','D3','G3','B3']].map(c=>c.map(midi));
const CH2=[null,null,null,null,null,null,[['C3','G3','C4','E4'],['D3','A3','D4','F#4']].map(c=>c.map(midi)),null];   // bar 7 splits C | D like the bass

let OCT=1;const MS=()=>[0,-12,-12][OCT],LS=()=>[0,0,-12][OCT];   // melody / left-hand shift in semitones
let AC=null,out=null,rev=null,playing=null,timer=null,t0=0,nextLoop=0,loopLen=0;
function init(){if(AC)return;const E=MUSIC.engine();AC=E.AC;out=E.out;rev=E.rev;}
const live=[];
function track(n){live.push(n);return n;}
// --- the game's voice (same as tone() in the game)
function chip(m,t,d,type,v){const o=track(AC.createOscillator()),g=AC.createGain();o.type=type;o.frequency.value=hz(m);
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(out);o.start(t);o.stop(t+d+.05);}
// --- piano voice: a few decaying partials + hammer click, brighter when louder, longer decay for low notes
function piano(m,t,d,v){const f=hz(m),decay=Math.max(.9,3.2-(m-40)*.045),rel=Math.min(d+.25,decay);
  const g=AC.createGain(),lp=AC.createBiquadFilter();lp.type='lowpass';lp.frequency.setValueAtTime(Math.min(9000,f*7+1500*v),t);lp.frequency.exponentialRampToValueAtTime(Math.max(600,f*2.2),t+decay*.6);lp.Q.value=.4;
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.006);g.gain.exponentialRampToValueAtTime(v*.35,t+.18);g.gain.exponentialRampToValueAtTime(.0008,t+rel+.35);
  [[1,1],[2,.42],[3,.18],[4,.09],[5.02,.04]].forEach(([h,a],i)=>{const o=track(AC.createOscillator()),og=AC.createGain();o.type=i?'sine':'triangle';o.frequency.value=f*h*(1+(i?.0007*i:0));o.detune.value=(i%2?2:-2);og.gain.value=a;o.connect(og);og.connect(lp);o.start(t);o.stop(t+rel+.4);});
  const nb=AC.createBuffer(1,AC.sampleRate*.03,AC.sampleRate),na=nb.getChannelData(0);for(let i=0;i<na.length;i++)na[i]=(Math.random()*2-1)*(1-i/na.length);
  const ns=track(AC.createBufferSource()),nf=AC.createBiquadFilter(),ng=AC.createGain();ns.buffer=nb;nf.type='bandpass';nf.frequency.value=Math.min(6000,f*4);ng.gain.value=v*.12;ns.connect(nf);nf.connect(ng);ng.connect(lp);ns.start(t);
  lp.connect(g);g.connect(out);g.connect(rev);}
// --- warm string pad
function pad(ms,t,d,v){const g=AC.createGain(),lp=AC.createBiquadFilter();lp.type='lowpass';lp.frequency.value=1400;
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.6);g.gain.setValueAtTime(v,t+d-.3);g.gain.linearRampToValueAtTime(0,t+d+.4);
  for(const m of ms)for(const det of[-7,6]){const o=track(AC.createOscillator());o.type='sawtooth';o.frequency.value=hz(m);o.detune.value=det;o.connect(lp);o.start(t);o.stop(t+d+.5);}
  lp.connect(g);g.connect(out);g.connect(rev);}

function scheduleLoop(v,t){
  if(v==='game'){const st=.22;loopLen=LOOP*st;
    for(const[tr,type,vol]of[[MEL,'triangle',.45],[BAS,'sine',.45],[ARP,'square',.06]]){let x=t,u=0,i=0;while(u<LOOP){const[m,l]=tr[i%tr.length];if(m)chip(m,x,l*st*.95,type,vol);x+=l*st;u+=l;i++;}}
    return;}
  const st=.25;loopLen=LOOP*st;
  // right hand: melody, gentle dynamics that rise into each phrase
  {let x=t,u=0;MEL.forEach(([m,l],i)=>{const ph=(u%16)/16;if(m)piano(m+MS(),x,l*st,(.34+.12*Math.sin(ph*Math.PI))*(OCT?1.15:1));x+=l*st;u+=l;});}
  // left hand: bass note on the bar, then a broken chord walking up
  for(let b=0;b<8;b++){const bt=t+b*8*st,parts=CH2[b]||[CH[b]];
    parts.forEach((c,pi)=>{const span=8/parts.length,ct=bt+pi*span*st;piano(c[0]+LS(),ct,span*st,OCT===2?.26:.3);
      const steps=span===8?[2,3,4,5,6]:[1,2,3];steps.forEach((s,k)=>piano(c[1+(k%3)]+LS(),ct+s*st*(span===8?1:1.3),st*1.6,.12));});}
  if(v==='pad')for(let b=0;b<8;b++)pad(CH[b].slice(1).map(m=>m+12+LS()+(OCT===1?-12:0)),t+b*8*st,8*st,.035);
}

let _timer=null,_ver=null;
function stop(){for(const n of live){try{n.stop();}catch(e){}}live.length=0;clearInterval(_timer);_timer=null;_ver=null;if(typeof loopN!=='undefined')loopN=0;}
function start(v){init();if(!AC)return;stop();_ver=v;t0=AC.currentTime+.15;scheduleLoop(v,t0);nextLoop=t0+loopLen;
  _timer=setInterval(()=>{if(AC.currentTime>nextLoop-2){scheduleLoop(v,nextLoop);nextLoop+=loopLen;}if(live.length>4000)live.splice(0,2000);},250);}
return{start,stop,get ver(){return _ver;}};
})();
